describe('[TEA] dispatcher — alias and negative routing', () => {
  it('[P1] scrape("fb","profile",...) alias routes correctly', async () => {
    const fakePage = {
      goto: async () => {},
      evaluate: async () => ({
        ogTitle: 'Test Page | Facebook',
